contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take three uint256 inputs and assert that setLimits does not revert when called by the access controller (this contract)
    function run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public payable {
        // initialize c so that this contract is the access controller
        // top-level state-changing call: initialize
        c.initialize(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setLimits(maxMultiplier, minMultiplier, rate); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: after initialize by this contract, calling setLimits must NOT revert
        assert(reverted == false);
    }

    receive() external payable {}
}

