pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    VaultAdapter c;

    function setUp() public {
        c = new VaultAdapter();
    }

    function _run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) internal {
        try c.initialize(address(this)) {} catch { return; }
        bool reverted;
        try c.setLimits(maxMultiplier, minMultiplier, rate) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == false);
    }

    function testFuzz_run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        _run(maxMultiplier, minMultiplier, rate);
    }

    receive() external payable {}
}
